# === G1 CLIMB v4: Google Drive 常時保存版(切断・再起動でも成果が消えない) ===
# 最初にDriveの認可ポップアップが1回出ます → アカウントを選んで許可してください
import base64, os, subprocess, sys

r = subprocess.run(["nvidia-smi", "-L"], capture_output=True, text=True)
assert r.returncode == 0 and r.stdout.strip(), \
    "GPUがありません: メニュー[ランタイム→ランタイムのタイプを変更→T4 GPU]を選んで再実行"
print(r.stdout.strip()); print("✅ GPU OK")

from google.colab import drive
drive.mount("/content/drive")
OUT_DIR = "/content/drive/MyDrive/g1_climb"
os.makedirs(OUT_DIR, exist_ok=True)
print("✅ Drive OK — 全チェックポイントを", OUT_DIR, "に逐次保存します")

subprocess.run([sys.executable, "-m", "pip", "install", "-q", "playground", "jax[cuda12]"])
import jax; print("JAX devices:", jax.devices())

open("g1_climb_mjx_env.py", "wb").write(base64.b64decode(""))
open("g1_train_colab.py", "wb").write(base64.b64decode(""))
print("✅ ファイル展開OK — スモークテスト→学習(150M、T4で約2時間)")

with open(OUT_DIR + "/train.log", "w") as logf:
    p = subprocess.Popen([sys.executable, "-u", "g1_train_colab.py", "--task", "climb",
                          "--steps", "150000000", "--out", OUT_DIR + "/g1_climb"],
                         stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
    for line in p.stdout:
        print(line, end="")
        logf.write(line)
        logf.flush()
    p.wait()
assert p.returncode == 0, "学習が異常終了 — 上のログを貼って報告してください"
print("🎉 完了 — 成果物はすべて Google Drive の MyDrive/g1_climb/ にあります")
print("   (zipダウンロード不要: Driveからいつでも取れます)")
